// Every test uses generated bytes. No real photo or video is ever read.

extension Data {
    init(hex: String) {
        precondition(hex.count.isMultiple(of: 2), "odd-length hex")
        var bytes: [UInt8] = []
        bytes.reserveCapacity(hex.count / 2)
        var index = hex.startIndex
        while index < hex.endIndex {
            let next = hex.index(index, offsetBy: 2)
            bytes.append(UInt8(hex[index..<next], radix: 16)!)
            index = next
        }
        self.init(bytes)
    }

    var hex: String {
        map { byte in
            let digits = String(byte, radix: 16)
            return digits.count == 1 ? "0" + digits : digits
        }.joined()
    }
}

extension SymmetricKey {
    var rawData: Data { withUnsafeBytes { Data($0) } }

    init(hex: String) {
        self.init(data: Data(hex: hex))
    }
}

extension UUID {
    init(rawBytes: Data) {
        precondition(rawBytes.count == 16)
        self.init(uuid: rawBytes.withUnsafeBytes { $0.loadUnaligned(as: type(of: UUID().uuid)) })
    }
}

func sha256Hex(_ data: Data) -> String {
    Data(SHA256.hash(data: data)).hex
}

/// Deterministic content, identical to `pattern()` in vault_reference.py.
func pattern(_ length: Int) -> Data {
    Data((0..<length).map { UInt8(truncatingIfNeeded: $0 &* 31 &+ 7) })
}

/// Reproducible pseudo-random numbers (SplitMix64) for picking test ranges
/// and tamper positions. Not used for anything cryptographic.
struct SplitMix64: RandomNumberGenerator {
    var state: UInt64

    mutating func next() -> UInt64 {
        state &+= 0x9E37_79B9_7F4A_7C15
        var z = state
        z = (z ^ (z >> 30)) &* 0xBF58_476D_1CE4_E5B9
        z = (z ^ (z >> 27)) &* 0x94D0_49BB_1331_11EB
        return z ^ (z >> 31)
    }
}

func randomData(_ length: Int, seed: UInt64) -> Data {
    var generator = SplitMix64(state: seed)
    return Data((0..<length).map { _ in UInt8.random(in: .min ... .max, using: &generator) })
}

/// Replays fixed bytes, in order, in place of the system random generator, so
/// tests can reproduce the reference vectors byte for byte.
final class FixedRandom: RandomBytesGenerator, @unchecked Sendable {
    private let lock = NSLock()
    private var remaining: [UInt8]

    init(_ chunks: Data...) {
        remaining = chunks.flatMap { [UInt8]($0) }
    }

    func bytes(_ count: Int) throws -> [UInt8] {
        lock.lock()
        defer { lock.unlock() }
        precondition(remaining.count >= count, "FixedRandom ran out of bytes")
        defer { remaining.removeFirst(count) }
        return Array(remaining.prefix(count))
    }

    var isExhausted: Bool {
        lock.lock()
        defer { lock.unlock() }
        return remaining.isEmpty
    }
}

/// Stands in for the Secure Enclave. `fixed` makes `createSecret` return a
/// known value for the reference vectors; otherwise it is random.
final class InMemoryDeviceSecret: DeviceSecretProvider, @unchecked Sendable {
    let binding: DeviceBinding
    private let lock = NSLock()
    private let fixed: SymmetricKey?
    private var secret: SymmetricKey?

    init(fixed: SymmetricKey? = nil, binding: DeviceBinding = .testing) {
        self.fixed = fixed
        self.binding = binding
    }

    func createSecret() throws -> SymmetricKey {
        lock.lock()
        defer { lock.unlock() }
        let new = fixed ?? SymmetricKey(size: .bits256)
        secret = new
        return new
    }

    func loadSecret() throws -> SymmetricKey {
        lock.lock()
        defer { lock.unlock() }
        guard let secret else { throw VaultError.deviceSecretMissing }
        return secret
    }

    func destroySecret() throws {
        lock.lock()
        defer { lock.unlock() }
        secret = nil
    }

    var exists: Bool {
        lock.lock()
        defer { lock.unlock() }
        return secret != nil
    }
}

final class InMemoryThrottleStore: ThrottleStateStore, @unchecked Sendable {
    private let lock = NSLock()
    private var state = ThrottleState()

    func load() throws -> ThrottleState {
        lock.lock()
        defer { lock.unlock() }
        return state
    }

    func save(_ newState: ThrottleState) throws {
        lock.lock()
        defer { lock.unlock() }
        state = newState
    }
}

/// A fresh, empty directory under the system temp folder. Never the real vault.
func temporaryVaultStore() -> VaultStore {
    VaultStore(directory: FileManager.default.temporaryDirectory
        .appendingPathComponent("VaultCoreTests-\(UUID().uuidString)", isDirectory: true))
}

extension KDFParameters {
    /// Cheap settings so the suite runs in seconds. Never used by the app.
    static let fastForTests = KDFParameters(opsLimit: 1, memLimitBytes: 8 << 20)
}

func passcode(_ text: String) -> [UInt8] {
    Array(text.utf8)
}
